function mapToWorld(cx, cy){ const cv = $('#v32MapCv'), r = cv.getBoundingClientRect(); return [MAP.cx + (cx - r.left - r.width/2)/MAP.z, MAP.cy + (cy - r.top - r.height/2)/MAP.z]; }
